ST.xhtml:p:
F_PowerOff(CLK := g_bDriveEnable);
IF F_PowerOff.Q THEN
  bEnable := FALSE;
END_IF;

(*防甩轴6*)

IF g_AntiRejection6Power.error THEN
  bEnable := FALSE;
END_IF;

AxisPowerBrake(
	bPower := bEnable,
    AxisRef := REF(AntiRejection6),
    HomeSignal :=g_AntiRejection6HomeSignal,
    HomeMode := g_nAvoidAxisHomeMode,
    AxisPosLimit := NOT g_bAntiRejection6PosLimit,
    AxisNegLimit := NOT g_bAntiRejection6NegLimit,
    AxisPower := REF(g_AntiRejection6Power),
    OutBrake => g_boAvoidAxisHoldBrake);


g_AntiRejection6SetOverRide.Enable := TRUE;
g_AntiRejection6SetOverRide.VelFactor := g_dCurOverride;
